const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const palmSprings = ee.Geometry.Point([-116.5453, 33.8303]);
  const startDate = '2017-06-15';
  const endDate = '2017-06-22'; // exclusive end date

  // 2. Data Acquisition & Check
  // Using MODIS Terra Daily LST (1km resolution)
  let collection = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(palmSprings);

  const colSize = collection.size().getInfo();
  console.log(`MODIS images found: ${colSize}`);

  if (colSize === 0) {
    console.log("No data available for the specified period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Extract day and night LST, apply QA mask
  function maskLST(image) {
    const qa = image.select('QC_Day');
    // QA bits 0-1: LST quality (00 = good)
    const goodQuality = qa.bitwiseAnd(3).eq(0);
    return image.updateMask(goodQuality);
  }

  collection = collection.map(maskLST);

  // 4. Calculation - Get maximum temperature across all days
  const lstDay = collection.select('LST_Day_1km');
  const maxLST = lstDay.max();

  // Check valid pixel count
  const pixelCount = maxLST.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: palmSprings,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log(`Valid pixels after QA masking: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No valid pixels after quality masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Get max temperature value
  const maxTempK = maxLST.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: palmSprings,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  // 5. Validation & Final Answer
  if (maxTempK === null || maxTempK === undefined) {
    console.log("Calculation failed - no valid result.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert from Kelvin to Fahrenheit
  // MODIS LST is in Kelvin * 0.02
  const maxTempKelvin = maxTempK * 0.02;
  const maxTempF = (maxTempKelvin - 273.15) * 9/5 + 32;

  console.log(`Max temperature: ${maxTempKelvin.toFixed(2)}K = ${maxTempF.toFixed(2)}°F`);

  // Sanity check
  if (maxTempF < -50 || maxTempF > 160) {
    console.log("Temperature outside reasonable range.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if reached 115°F
  if (maxTempF >= 115.0) {
    console.log(`Temperature reached/exceeded 115°F (${maxTempF.toFixed(1)}°F)`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`Temperature did not reach 115°F (max: ${maxTempF.toFixed(1)}°F)`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
